-- Schema SQL Supabase 
CREATE TABLE IF NOT EXISTS public.readers ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, status TEXT DEFAULT 'free', access_token TEXT UNIQUE NOT NULL, referral_code TEXT UNIQUE NOT NULL, referred_by TEXT, pagarme_order_id TEXT, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() ); 
CREATE TABLE IF NOT EXISTS public.reader_traits ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), reader_id UUID REFERENCES public.readers(id) ON DELETE CASCADE, interactions JSONB DEFAULT '{}'::jsonb, hypotheses JSONB DEFAULT '[]'::jsonb, explored_links JSONB DEFAULT '[]'::jsonb, reading_progress JSONB DEFAULT '{\\" "max_chapter\: 1}'::jsonb, updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() ); 
CREATE TABLE IF NOT EXISTS public.referral_chain ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), referrer_id UUID REFERENCES public.readers(id) ON DELETE CASCADE, converted_reader_id UUID REFERENCES public.readers(id) ON DELETE CASCADE, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() ); 
